package einoruntime

import "context"

// Implementations for the component stubs generated by Eino Dev. Regenerate
// topology into a separate directory, then review it before replacing the
// builder, so business and permission components are never overwritten.
func newLambda(ctx context.Context, input string) (string, error)  { return planReview(ctx, input) }
func newLambda1(ctx context.Context, input string) (string, error) { return retrieveReview(ctx, input) }
func newLambda2(ctx context.Context, input string) (string, error) { return analyseReview(ctx, input) }
func newLambda3(ctx context.Context, input string) (string, error) { return validateReview(ctx, input) }
